 * Finds the exact GitHub Actions run for a commit and waits for its bounded completion.
 *
 * @param input.discoveryAttempts - Run searches before failing (1-12). The default is 3.
 * @param input.discoveryIntervalMs - Delay between searches (1000-30000). The default is 5000 ms.
 * @param input.timeoutMs - Wall-clock limit for discovery and the wait together (at least 1000;
 *   larger values are capped at 285000, under the tool's 300 s call limit).
 *   The default is 240000 ms; ci.waitForRun gets what discovery leaves.
 *   ci.findRun and ci.waitForRun validate the remaining inputs.
 */
async function waitForCommit(
  { ci: { findRun, waitForRun } },
  input: {
    repo: string;
    sha: string;
    runName?: string;
    limit?: number;
    discoveryAttempts?: number;
    discoveryIntervalMs?: number;
    attempts?: number;
    intervalMs?: number;
    initialDelayMs?: number;
    timeoutMs?: number;
    raise?: boolean;
  },
) {
  const integerInput = (
    name: string,
    value: number | undefined,
    fallback: number,
    min: number,
    max: number,
  ) => {
    const chosen = value ?? fallback;
    if (!Number.isInteger(chosen) || chosen < min || chosen > max) {
      throw new Error(`${name} must be an integer between ${min} and ${max}`);
    }
    return chosen;
  };
  const discoveryAttempts = integerInput("discoveryAttempts", input.discoveryAttempts, 3, 1, 12);
  const discoveryIntervalMs = integerInput(
    "discoveryIntervalMs",
    input.discoveryIntervalMs,
    5000,
    1000,
    30000,
  );
  // A larger limit could not finish inside one tool call, so cap it rather than reject it (#379).
  const requestedTimeoutMs =
    input.timeoutMs === undefined ? undefined : Math.min(input.timeoutMs, 285000);
  const timeoutMs = integerInput("timeoutMs", requestedTimeoutMs, 240000, 1000, 285000);
  const deadline = Date.now() + timeoutMs;
  let match: Awaited<ReturnType<typeof findRun>>["matches"][number] | undefined;
  let slowestFindMs = 0;
  let stoppedEarly = false;
  for (let attempt = 1; attempt <= discoveryAttempts; attempt++) {
    const started = Date.now();
    const found = await findRun({
      repo: input.repo,
      sha: input.sha,
      limit: input.limit,
      runName: input.runName,
    });
    slowestFindMs = Math.max(slowestFindMs, Date.now() - started);
    match = found.matches[0];
    if (match) break;
    if (attempt < discoveryAttempts) {
      // Stop looking once another wait and lookup would overrun the deadline.
      if (Date.now() + discoveryIntervalMs + slowestFindMs > deadline) {
        stoppedEarly = true;
        break;
      }
      await new Promise<void>((resolve) => setTimeout(resolve, discoveryIntervalMs));
    }
  }
  if (!match) {
    throw new Error(
      `No${input.runName ? ` ${JSON.stringify(input.runName)}` : ""} GitHub Actions run found for ${input.sha}${stoppedEarly ? ` before its ${timeoutMs / 1000} s time limit` : ""}`,
    );
  }
  const run = await waitForRun({
    id: match.id,
    repo: input.repo,
    attempts: input.attempts,
    intervalMs: input.intervalMs,
    initialDelayMs: input.initialDelayMs ?? (match.status === "completed" ? 0 : undefined),
    // The run's wait gets whatever time discovery left.
    timeoutMs: Math.max(1000, deadline - Date.now()),
    raise: input.raise,
  });
  return { match, run };
}
