    status: "timed_out",
    id: input.id,
    attempts: attempt,
    requestedAttempts,
    timeoutMs,
    elapsedMs,
    lastStatus: last?.status,
    url: last?.url,
    jobs: summarizeJobs(last?.jobs),
  };
}
